                    ? "text-blue-700"
                    : "text-muted-foreground",
              )}
            >
              {stage.label}
            </p>
          </div>
          {stage.status === "running" && (
            <span className="text-xs text-muted-foreground">{stage.elapsed.toFixed(0)}s</span>
